// Offline Natural Earth context for the unchanged 50-state Statle map.
// Rebuild: node scripts/build-us-context.cjs [--check]
// Source extraction, lake subtraction and coordinate alignment are documented in
// docs/us-map-context-sources.md. No geographic library or network is needed.
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '..');
const SOURCE_B64 = '';
const sourceText = zlib.gunzipSync(Buffer.from(SOURCE_B64, 'base64')).toString('utf8');
const sourceHash = 'adf024271a2a58bb65fded39fe82b9dabf2a467e39f0928083cf0d64ab099a34';
assert.equal(crypto.createHash('sha256').update(sourceText).digest('hex'), sourceHash, 'Embedded source checksum');
const source = JSON.parse(sourceText);
// The original state paths are rounded to 0.1 units. These parameters align
// their Census coordinates with a median residual of 0.124 source SVG units.
const projection = {
  main: {name:'Albers equal-area', parallels:[29.5,45.5], rotate:[96,0], center:[-.6,38.7], scale:983.5892427316285, translate:[499.6372552186457,247.90855578188942]},
  AK: {name:'equirectangular', scale:4.169974327844517, translate:[824.0256300273641,770.5588802583964]}
};
const rad = Math.PI / 180;
const n = (Math.sin(29.5*rad) + Math.sin(45.5*rad)) / 2;
const c = Math.cos(29.5*rad)**2 + 2*n*Math.sin(29.5*rad);
const rho0 = Math.sqrt(c) / n;
function rawAlbers(lon,lat) {
  const rho = Math.sqrt(c - 2*n*Math.sin(lat*rad)) / n;
  return [rho*Math.sin(lon*rad*n), rho0-rho*Math.cos(lon*rad*n)];
}
const center = rawAlbers(-.6,38.7);
function project(point, area) {
  const [lon,lat] = point, p = projection[area];
  if(area === 'AK') return [p.translate[0]+p.scale*(lon>0?lon-360:lon),p.translate[1]-p.scale*lat];
  const raw = rawAlbers(lon+96,lat);
  return [p.translate[0]+p.scale*(raw[0]-center[0]),p.translate[1]-p.scale*(raw[1]-center[1])];
}
function polygons(geometry) { return geometry.type === 'Polygon' ? [geometry.coordinates] : geometry.coordinates; }
function rounded(value) { return String(Number(value.toFixed(3))); }
// Straight geographic parallels become curved in Albers. Resample long edges
// before projecting, rather than joining only their projected endpoints.
function resample(ring,area) {
  const points=[];
  for(let i=0;i<ring.length-1;i++) {
    const a=ring[i],b=ring[i+1],steps=area==='main'?Math.max(1,Math.ceil(Math.max(Math.abs(b[0]-a[0]),Math.abs(b[1]-a[1]))/.1)):1;
    for(let j=0;j<steps;j++)points.push([a[0]+(b[0]-a[0])*j/steps,a[1]+(b[1]-a[1])*j/steps]);
  }
  points.push(ring.at(-1));return points;
}
function pathFor(geometry, area) {
  return polygons(geometry).map(polygon => polygon.map(ring => {
    const points=resample(ring,area).map(point=>project(point,area));
    return points.map((point,i)=>(i?'L':'M')+point.map(rounded).join(' ')).join('')+'Z';
  }).join('')).join('');
}
function insideRing(point,ring) {
  let inside=false;
  for(let i=0,j=ring.length-1;i<ring.length;j=i++) {
    const a=ring[i],b=ring[j];
    if((a[1]>point[1])!==(b[1]>point[1]) && point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;
  }
  return inside;
}
function contains(name,area,point) {
  const feature=source.features.find(feature=>feature.n===name&&feature.area===area);
  return polygons(feature.geometry).some(polygon=>insideRing(point,polygon[0])&&!polygon.slice(1).some(ring=>insideRing(point,ring)));
}
for(const point of [[-100,50],[-82,46.5],[-80.5,43.5],[-100,49.05],[-100,60]]) assert(contains('Canada','main',point),'Canada land retained at '+point);
assert(contains('Mexico','main',[-105,30]),'Mexico land retained');
assert(contains('Mexico','main',[-100,20]),'Southern Mexico retains its natural outline');
assert(contains('Canada','AK',[-138,65]),'Canadian land beside Alaska retained');
for(const point of [[-87.5,47.5],[-82.4,44.7],[-81,42.1],[-77.9,43.65],[-87,43.7]]) assert(!contains('Canada','main',point),'Great Lakes remain water at '+point);
assert(!contains('Canada','main',[-100,48.95]),'Canadian context does not cover North Dakota');
const areas={main:[],AK:[]};
for(const feature of source.features) areas[feature.area].push({n:feature.n,d:pathFor(feature.geometry,feature.area)});
// Check the emitted SVG as well as the geographic extract: a long geographic
// border must retain its projected curve, not become a chord across Canada.
const canadaPath=areas.main.find(country=>country.n==='Canada').d;
const canadaRings=canadaPath.split('M').slice(1).map(ring=>[...ring.matchAll(/(?:^|L)(-?[0-9.]+) (-?[0-9.]+)/g)].map(match=>[Number(match[1]),Number(match[2])]));
const svgContains=point=>canadaRings.filter(ring=>insideRing(point,ring)).length%2===1;
assert(svgContains([462.031895,68.918248]),'Projected Canadian border follows the 49th parallel');
assert(!svgContains([461.960563,70.612150]),'Projected Canadian border stays north of North Dakota');
const stateText=fs.readFileSync(path.join(root,'assets/geography/us-states.json'),'utf8').replace(/\r\n/g,'\n');
assert.equal(crypto.createHash('sha256').update(stateText).digest('hex'),'6416e46fca2d99ab44d3774ecf39b96466b56e35bf2dc57b4bb669afd0a61434','Re-align USA context if the state geometry changes');
const data={version:1,source:{name:'Natural Earth 1:10m (public domain)',countries:'https://github.com/nvkelso/natural-earth-vector/blob/master/geojson/ne_10m_admin_0_countries.geojson',countriesSha256:'239eec57ac17f100a11e2536cffc56752c318b50ae765b0918ff7aab4ce8f255',lakes:'https://github.com/nvkelso/natural-earth-vector/blob/master/geojson/ne_10m_lakes.geojson',lakesSha256:'2d036f53dedec578001c5c30c2959ee7d4eebc1306900fa4367c49929ec8f2d9',extractSha256:sourceHash,stateSha256:crypto.createHash('sha256').update(stateText).digest('hex'),crop:{main:[-142,14,-50,84],AK:[-142,53,-127,72.5]},simplificationDegrees:.004,waterExcluded:['Lake Superior','Lake Michigan','Lake Huron','Lake Erie','Lake Ontario']},projection,areas};
const output=JSON.stringify(data)+'\n',destination=path.join(root,'assets/geography/us-context.json');
if(process.argv.includes('--check')) assert.equal(fs.readFileSync(destination,'utf8').replace(/\r\n/g,'\n'),output,'Rebuild the USA context asset');
else fs.writeFileSync(destination,output);
console.log('PASS USA context: Canada and Mexico, Alaska neighbour, five Great Lakes remain water'+(process.argv.includes('--check')?' (offline asset matches)':''));
